const e=[{id:1,icon:"FireExtinguisher",accent:"#dc2626",title:"تەمرینکا ئاگری",subtitle:"ڕێکارا P.A.S.S و جۆرێن تەمرینکان",summary:"تەمرینکا ئاگری (Fire Extinguisher) ئامێرەکێ سەرەکی یە د بەرگرییا شارستانیدا. ئەڤ وانە ڤان بابەتان بخوە ڤە دگریت: جۆرێن تەمرینکان (ئاڤ، کەف، CO₂، تۆزا هشک، کیمیایا تەڕ و ماددێن پاقژ)، پۆلێن ئاگری ل گۆر سیستەمێ NFPA (A، B، C، D، K)، ڕێکارا P.A.S.S، پشکنینا هەیڤانە و خزمەتکرنا سالانە، سەلامەتییا بکارئینانێ و سیناریۆیێن ڕاستەقینە. ئەڤ زانیاری بۆ قوتابیێن قۆناغا ناڤەندی و ئامادەیی یە، داکو بزانن مەزنێن ڕاهێنان دیتی چەوا تەمرینکێ بکار دئینن. د ئاگرەکێ ڕاستەقینە دا، کارێ قوتابیان ئەوە: کەسێن دی ئاگەهدار بکەن، دەرکەڤن و گازی ١١٥ بکەن.",blocks:[{heading:"جۆرێن تەمرینکان و بکارئینانا وان",body:`• تەمرینکا ئاڤێ (Water): بۆ ئاگرێن پۆلا A (تشتێن ئاسایی وەکی دار، کاغەز و قوماش). ئاڤ گەرمییێ کێم دکەت. چ جاران بۆ ئاگرێن کارەبێ یان ڕۆنی بکار نەئینە!
• تەمرینکا کەفێ (Foam/AFFF): بۆ پۆلا A و B (شلەمەنییێن سووتەنی). کەف چینەکێ ل سەر ئاگری چێدکەت و ڕێکێ ل ئۆکسجینێ دگریت.
• تەمرینکا CO₂: بۆ پۆلا B و C (شلەمەنی و ئامێرێن کارەبێ). CO₂ ئۆکسجینێ ژ ئاگری دبڕیت و چ پاشماوە ناهێلیت؛ باشترە بۆ ئامێرێن ئەلکترۆنی و تاقیگەهان.
• تەمرینکا تۆزا هشک (Dry Chemical/ABC): بۆ پۆلا A، B و C. بەلاڤترین جۆرە. تۆزا کیمیایی کارلێکرنا کیمیایی یا ئاگری ڕادگریت. ئاگەهدار بە: تۆزا ABC بۆ پۆلا D (کانزا) و پۆلا K (ڕۆنێ مەتبەخێ) نابیت.
• تەمرینکا کیمیایا تەڕ (Wet Chemical): تایبەتە بۆ پۆلا K (ئاگرێن مەتبەخێ و ڕۆنێ قەلاندنێ). ڕۆنی دکەتە وەکی سابوونێ (saponification) و چینەکێ پاراستنێ ل سەر چێدکەت.
• تەمرینکا ماددێن پاقژ (Clean Agent): بۆ ئامێرێن هەستیار وەکی کۆمپیوتەر و سێرڤەران. پاشماوە ناهێلیت و زیانێ ناگەهینیتە ئامێران.`,image:"media/images/ext_types_all.png"},{heading:"ڕێکارا P.A.S.S (هەنگاڤ ب هەنگاڤ)",body:`P = Pull (بکێشە): ئەلقەیا سەلامەتییێ (safety pin) بکێشە و دەربێخە. ئەڤ ئەلقە دەسکێ تەمرینکێ قفل دکەت.

A = Aim (ئاراستە بکە): سەرێ لوولەیا تەمرینکێ بەرەڤ بنێ ئاگری ئاراستە بکە، نە بەرەڤ سەرێ ئاگری! ئەگەر بەرەڤ سەرێ ئاگری ئاراستە بکەی، ئاگر ڤەنامریت و دبیت بەلاڤ ببیت.

S = Squeeze (فشار بدە): دەسکێ تەمرینکێ ب هێمنی و قایمی فشار بدە. ئەگەر دەسکی بەردەی، ماددە ڕادوەستیت؛ ب ڤی ڕەنگی تو دشێی کۆنترۆل بکەی.

S = Sweep (بلڤینە): لوولەیێ ل بنێ ئاگری ژ لایەکی بۆ لایێ دی بلڤینە، هەتا ئاگر ب تەمامی ڤەدمریت. ئەگەر ئاگر دووبارە گرت، P.A.S.S دووبارە بکە.

دوورییا سەلامەت: ٢–٣ مەتران دوور ژ ئاگری ڕاوەستە. هەمیشە ڕێکا دەرکەفتنێ ل پشت خوە بهێلە.`,image:"media/images/pass_detailed.png"},{heading:"پشکنینا هەیڤانە و خزمەتکرنا سالانە",body:`پشکنینا هەیڤانە (ب چاڤان):
• جهـ: تەمرینک ل جهێ خوە یێ دیار بیت، ب دیواری ڤە هەلاویستی و نێزیکی دەرگەهی؛ سەرێ وێ ژ ١.٥ مەتران بلندتر نەبیت ژ عەردی (NFPA 10)
• پیڤەرێ فشارێ (pressure gauge): دەرزی د ناڤا پشکا کەسک دا بیت
• ئەلقەیا سەلامەتییێ و مۆرا پلاستیکی (seal): ل جهێ خوە بن و نەشکەستی بن
• لوولە و شلانگ: بێ شکەستن، بێ قلیش و بێ گیرانێ بن
• لەشێ تەمرینکێ: بێ ژەنگ، بێ چەمیان و بێ زیان
• کارتا خزمەتکرنێ (service tag): مێژوویا دووماهیک خزمەتکرنا سالانە ل سەر بیت

خزمەتکرنا سالانە و پڕکرنەڤە:
• پسپۆڕەک هەر سال تەمرینکان تاقی دکەت و خزمەت دکەت
• تاقیکرنا فشارێ (Hydrostatic test) هەر ٥ یان ١٢ سالان جارەکێ ل گۆر جۆرێ تەمرینکێ (NFPA 10)؛ ئەڤە تاقیکرنە، نە گوهۆڕینا تەمرینکێ
• پشتی هەر بکارئینانەکێ (حەتا ئەگەر کێم ژی بیت)، تەمرینک دڤێت ئێکسەر بهێتە پڕکرنەڤە`,image:"media/images/ext_inspection.png"}],examples:["تەمرینکا ABC بەلاڤترین جۆرە، بۆ مال و قوتابخانان","CO₂ بۆ تاقیگەهـ و ئامێرێن ئەلکترۆنی","کیمیایا تەڕ (Wet Chemical) تایبەتە بۆ ئاگرێن مەتبەخێ (K)","دووری د ڕێکارا P.A.S.S دا: ٢–٣ مەتر","پشکنینا هەیڤانە: فشار + ئەلقە + لوولە + کارتا خزمەتکرنێ","پڕکرنەڤە پشتی هەر بکارئینانەکێ؛ خزمەتکرنا پسپۆڕی هەر سال","هەمیشە ڕێکا دەرکەفتنێ ل پشت خوە بهێلە","تەمرینکا مالێ ب گشتی سڤکە (نێزیکی ٢–٥ کگم)"],tips:["ڕەنگێن تەمرینکان ل گۆر ستاندارا ئەورووپی BS EN 3: سوور = ئاڤ، کرێمی = کەف، ڕەش = CO₂، شین = تۆزا هشک، زەرد = کیمیایا تەڕ","P.A.S.S ژبەر بکە: Pull، Aim، Squeeze، Sweep","دووری: ٢–٣ مەتران ژ ئاگری ڕاوەستە","ڕێکا دەرکەفتنێ هەمیشە ل پشت خوە بهێلە","ئەگەر ئاگر د چەند چرکێن ئێکێ دا کێم نەبوو یان تەمرینک ڤالا بوو، ئێکسەر دەرکەڤە و گازی ١١٥ بکە"],warnings:["چ جاران تەمرینکا ئاڤێ بۆ ئاگرێن کارەبێ (C) یان ڕۆنێ داخ (K) بکار نەئینە! ئاڤ کارەبێ دگەهینیت و ڕۆنێ داخ ب هێز بەلاڤ دکەت. تەمرینکێ تەنێ بۆ ئاگرێن بچووک و د دەستپێکێ دا بکار بینە؛ ئەگەر ئاگر ژ تە مەزنتر بوو، ئێکسەر دەرکەڤە و گازی ١١٥ بکە!"],realCase:"ل مەتبەخەکێ ل دهۆکێ، ڕۆنێ قەلاندنێ ئاگر گرت. کارمەندەکێ فێرکری تەمرینکا کیمیایا تەڕ (K) بکار ئینا و ب ڕێکارا P.A.S.S د ٢٠ چرکەیاندا ئاگر ڤەمراند. ئەگەر تەمرینکا ئاڤێ بکار ئینابا، ئاگر دا ب هێز بەلاڤ بیت و کارەساتەکا مەزن دا چێبیت. زانینا جۆرێن تەمرینکان ژیان پاراستن!",video:"media/videos/lesson_extinguisher_full.mp4",game:{instruction:"هەر جۆرەکێ تەمرینکێ بۆ کیژ پۆلا ئاگری یە؟ یێن دروست هەلبژێرە:",items:[{text:"تەمرینکا CO₂ → ئاگرێ کارەبێ (C)",emoji:"🔵",correct:!0},{text:"تەمرینکا ئاڤێ → ئاگرێ ڕۆنێ مەتبەخێ (K)",emoji:"💧",correct:!1},{text:"تەمرینکا ABC → ئاگرێن پۆلا A، B و C",emoji:"🔴",correct:!0},{text:"تەمرینکا کەفێ → ئاگرێ کانزایان (D)",emoji:"🟡",correct:!1}]},activity:{prompt:"تو د تاقیگەها کیمیایێ دا یی ل قوتابخانێ. ژ نشکەکێ ڤە ئاگرەک ل سەر مێزێ چێبوو: شلەمەنییەکا ئۆرگانیک یا سووتەنی (پۆلا B) ئاگر گرت و نێزیکی ئامێرێن کارەبێ (پۆلا C) ژی یە. دوو تەمرینک ل وێرێ هەنە: تەمرینکا ئاڤێ و تەمرینکا CO₂. دێ چ کەی؟",image:"media/images/activity_lab_fire.png",options:[{text:"ب دەنگەکێ بلند دبێژم «ئاگر!» دا کو مامۆستا و هەڤالان ئاگەهدار بکەم، ژ نێزیکترین دەرگەهی ژ تاقیگەهێ دەردکەڤین و دەرگەهی ل پشت خوە دگرین، و ژ دەرڤە گازی ١١٥ دکەم. تەنێ مامۆستا یان کارمەندێن ڕاهێنای بڕیارێ ددەن کا تەمرینکا CO₂ بۆ ئاگرەکێ بچووک بکار بینن یان نە.",correct:!0},{text:"تەمرینکا ئاڤێ بۆ ئاگری بکار دئینم",correct:!1},{text:"ب خوە تەمرینکا CO₂ بۆ ئاگری بکار دئینم",correct:!1,feedback:"قوتابی ئاگری ڤەنامرینن. کەسێن دی ئاگەهدار بکە، دەرکەڤە و گازی ١١٥ بکە."},{text:"بێی ئاگەهدارکرنا مامۆستا و هەڤالان ب تەنێ دەردکەڤم",correct:!1}]},quiz:[{question:"P.A.S.S واتایا چ یە؟",options:[{text:"Pull, Aim, Squeeze, Sweep",correct:!0,feedback:"دروستە! بکێشە، ئاراستە بکە، فشار بدە، بلڤینە."},{text:"Push, Aim, Spray, Stop",correct:!1,feedback:"نەخێر!"},{text:"Pull, Attack, Spray, Sweep",correct:!1,feedback:"نەخێر!"}]},{question:"کیژ تەمرینک بۆ ئاگرێن کارەبێ (C) باشترە؟",options:[{text:"CO₂",correct:!0,feedback:"دروستە! CO₂ چ پاشماوە ناهێلیت و کارەبێ ناگەهینیت."},{text:"ئاڤ",correct:!1,feedback:"نەخێر! ئاڤ کارەبێ دگەهینیت."},{text:"کیمیایا تەڕ (K)",correct:!1,feedback:"نەخێر! ئەو بۆ ئاگرێن مەتبەخێ یە."}]},{question:"تەمرینکا کیمیایا تەڕ (Wet Chemical) تایبەتە بۆ چ؟",options:[{text:"ئاگرێن ڕۆنێ قەلاندنێ و مەتبەخێ",correct:!0,feedback:"دروستە! ڕۆنی دکەتە وەکی سابوونێ و ئاگری دخەندقینیت."},{text:"ئاگرێن ئاسایی وەکی دار",correct:!1,feedback:"نەخێر!"},{text:"ئاگرێن کانزایان (D)",correct:!1,feedback:"نەخێر! پۆلا D پێدڤی ب تۆزەکا تایبەت هەیە."}]},{question:"دوورییا سەلامەت د ڕێکارا P.A.S.S دا چەندە؟",options:[{text:"٢–٣ مەتر",correct:!0,feedback:"دروستە!"},{text:"١٠ مەتر",correct:!1,feedback:"نەخێر، گەلەک دوورە و ماددە ناگەهیتە ئاگری."},{text:"هندی نێزیکتر باشترە",correct:!1,feedback:"نەخێر، مەترسیدارە!"}]},{question:"پشکنینا تەمرینکان دڤێت کەنگی بهێتە کرن؟",options:[{text:"هەر هەیڤ (ب چاڤان) و هەر سال (ژ لایێ پسپۆڕان ڤە)",correct:!0,feedback:"دروستە!"},{text:"تەنێ دەمێ بکارئینانێ",correct:!1,feedback:"نەخێر!"},{text:"هەر ٥ سالان جارەکێ",correct:!1,feedback:"نەخێر! ئەڤە دەمێ تاقیکرنا فشارێ یە بۆ هندەک جۆران، نە پشکنینا ئاسایی."}]}]},{id:2,icon:"FlameKindling",accent:"#ea580c",title:"پۆلێن ئاگری A-B-C-D-K",subtitle:"ناسینا جۆرێن ئاگری و ڕێکارێن ڤەمراندنێ",summary:"ئاگر هەمی نە ئێک جۆرن. هەر جۆرەکێ ئاگری پێدڤی ب ڕێکارەکا جودا هەیە. ناسینا پۆلێن ئاگری ل گۆر سیستەمێ ئەمریکی NFPA (A، B، C، D، K) بنەمایێ کارێ هەر ئاگرکوژەکی یە. د سیستەمێ ئەورووپی EN 2 دا پۆل هندەک جودانە: C بۆ غازان، F بۆ ڕۆنێ مەتبەخێ، و کارەبا نە پۆلەکا جودا یە. ئەگەر ڕێکارا خەلەت بکار بینی، ئاگر دێ خرابتر لێ هێت.",blocks:[{heading:"پۆلا A: تشتێن ئاسایی",body:`• چ یە: دار، کاغەز، قوماش، پلاستیک؛ تشتێن ئاسایی یێن هشک کو ئاگر دگرن
• ڕێکار: ئاڤ (سارکرن)، کەف، تۆزا ABC
• هێما (NFPA): سێگۆشەیەکا کەسک ب پیتا A
• نموونە: ئاگرێن مالان، سەتلێن گلێشی، پەردە`,image:"media/images/class_a.png"},{heading:"پۆلا B، C، D و K (NFPA)",body:`• B: شلەمەنی و غازێن سووتەنی: بەنزین، نەفت، ئەلکهول، تینەر، غاز. ڕێکار: کەف، CO₂، تۆزا ABC. چ جاران ئاڤێ بکار نەئینە!
• C: ئامێرێن کارەبێ یێن ب کارەبا: وایەر، ئامێر و تابلۆیێن کارەبێ. ئێکەم جار، ئەگەر ب سەلامەتی بشێی، کارەبێ ببڕە. ڕێکار: CO₂، تۆزا ABC.
• D: کانزایێن سووتەنی: مەگنیسیۆم، تیتانیۆم، سۆدیۆم. ڕێکار: تۆزا تایبەت یا پۆلا D. ئاڤ مەترسیدارە و تۆزا ABC کار ناکەت!
• K: ڕۆنێ مەتبەخێ یێ داخ. ڕێکار: کیمیایا تەڕ (Wet Chemical)، یان قەپاخەکێ بدە سەر تاوەیێ و ئاگرێ بن تاوەیێ بگرە. ئاڤ کارەساتە و تۆزا ABC نە بەسە!`,image:"media/images/class_bcdk.png"},{heading:"سێگۆشەیا ئاگری و ڕێکێن ڤەمراندنێ",body:`ئاگر ژ سێ تشتان پێکدهێت: گەرمی + سووتەمەنی + ئۆکسجین (O₂). ئەگەر ئێک ژ وان بهێتە ڕاکرن، ئاگر ڤەدمریت.
• سارکرن (Cooling): ئاڤ گەرمییا ئاگری کێم دکەت → پۆلا A
• خەندقاندن (Smothering): کەف یان CO₂ ئۆکسجینێ ژ ئاگری دبڕن → پۆلا B
• ڕاکرنا سووتەمەنییێ: سووتەمەنییێ ژ ئاگری دوور بێخە، وەکی گرتنا کێلۆنا غازێ
• ڕاوەستاندنا کارلێکرنا زنجیرەیی: تۆزا کیمیایی کارلێکرنا کیمیایی یا ئاگری ڕادگریت → تۆزا ABC`,image:"media/images/fire_triangle_adv.png"}],examples:["A = دار و کاغەز → ئاڤ","B = بەنزین و غاز → کەف و CO₂","C = کارەبا → CO₂","D = کانزا → تۆزا تایبەت یا پۆلا D","K = ڕۆنێ داخ → کیمیایا تەڕ (Wet Chemical)","ئاڤ + ڕۆنێ داخ = تەقین و بەلاڤبوونا ئاگری!","ئاڤ + کارەبا = لێدانا کارەبێ (شۆک)!","سێگۆشەیا ئاگری: گەرمی + سووتەمەنی + O₂"],tips:["پۆلێن ئاگری ب هێمایێن وان بناسە","ئاڤ تەنێ بۆ پۆلا A یە","CO₂ بۆ پۆلا B و C یە","کیمیایا تەڕ (Wet Chemical) بۆ پۆلا K یە"],warnings:["چ جاران ئاڤێ ل سەر ئاگرێ ڕۆنی (K) نەڕێژە! ئاڤ ل بن ڕۆنێ داخ ئێکسەر دبیتە هەلم، ڕۆنێ ب ئاگر ب هێز بلند دکەت و ئاگرەکێ مەزن ب لەز بەلاڤ دبیت. ئەڤە گەلەک مەترسیدارە."],realCase:"ل کارگەهەکێ ل هەولێرێ، ئاگرێ کانزایەکێ (پۆلا D، مەگنیسیۆم) چێبوو. کارمەندەکی ب ئاڤێ هەول دا ئاگری ڤەمرینیت، بەلێ ئاگر ب هێز مەزنتر لێ هات! پاشان پسپۆڕەکی تۆزا تایبەت یا پۆلا D بکار ئینا و ئاگر ڤەمراند. زانینا پۆلێن ئاگری ژیانێ دپارێزیت!",video:"media/videos/lesson_fire_classes.mp4",game:{instruction:"هەر پۆلەکا ئاگری ب ڕێکارا وێ یا دروست ڤە گرێبدە:",items:[{text:"ڕۆنێ داخ (K) → کیمیایا تەڕ",emoji:"🍳",correct:!0},{text:"کاغەز (A) → ئاڤ",emoji:"📄",correct:!0},{text:"بەنزین (B) → کەف یان CO₂",emoji:"⛽",correct:!0},{text:"کارەبا (C) → ئاڤ",emoji:"⚡",correct:!1}]},activity:{prompt:"د مەتبەخا قوتابخانێدا ڕۆنێ قەلاندنێ ئاگر گرتییە. تەمرینکەکا ئاڤێ و تەمرینکەکا کیمیایا تەڕ (K) ل وێرێ هەنە. دێ چ کەی؟",image:"media/images/activity_kitchen_fire.png",options:[{text:"ژ سۆبێ دویر دکەڤم، ب دەنگەکێ بلند دبێژم «ئاگر!» دا کو کارمەندێن مەتبەخێ و مامۆستا ئاگەهدار بکەم، دەردکەڤم و گازی ١١٥ دکەم. مەزنەکێ ڕاهێنان دیتی سۆبێ ڤەدکوژینیت و قەپاخەکێ ددەتە سەر تاوێ، یان تەمرینکا کیمیایا تەڕ (K) بکار دئینیت.",correct:!0},{text:"ئاڤێ دڕێژمە سەر ڕۆنێ داخ",correct:!1},{text:"دچمە نێزیکی تاوێ و ب خوە تەمرینکا کیمیایا تەڕ (K) بکار دئینم",correct:!1,feedback:"قوتابی ناچنە نێزیکی تاوەیەکا ب ئاگر؛ ئەڤە کارێ مەزنێن ڕاهێنان دیتی یە. دەرکەڤە و گازی ١١٥ بکە."},{text:"تاوەیا ب ئاگر هەلدگرم و دبەمە دەرڤە",correct:!1}]},quiz:[{question:"ئەگەر ئاڤ ل سەر ئاگرێ ڕۆنی (K) بهێتە ڕێتن، دێ چ چێبیت؟",options:[{text:"تەقین و بەلاڤبوونا ئاگری",correct:!0,feedback:"دروستە! ئاڤ دبیتە هەلم و ڕۆنێ ب ئاگر بەلاڤ دکەت."},{text:"ئاگر ڤەدمریت",correct:!1,feedback:"نەخێر!"},{text:"چ تشت نابیت",correct:!1,feedback:"نەخێر!"}]},{question:"د ئاگرێ پۆلا C (کارەبا) دا، هەنگاڤا ئێکێ چ یە؟",options:[{text:"ئەگەر ب سەلامەتی ببیت، کارەبێ ببڕە",correct:!0,feedback:"دروستە! پاشان CO₂ بکار بینە."},{text:"ئاڤێ بڕێژە",correct:!1,feedback:"نەخێر!"},{text:"چ تشتی نەکە",correct:!1,feedback:"نەخێر!"}]},{question:"سێگۆشەیا ئاگری ژ چ پێکدهێت؟",options:[{text:"گەرمی + سووتەمەنی + ئۆکسجین",correct:!0,feedback:"دروستە!"},{text:"ئاڤ + با + گەرمی",correct:!1,feedback:"نەخێر!"},{text:"دوکێل + ئاگر + هەوا",correct:!1,feedback:"نەخێر!"}]}]},{id:3,icon:"Activity",accent:"#d97706",title:"عەردەهەژین: ئاستێ پێشکەفتی",subtitle:"سەلامەتییا ئاڤاهیان و ڕزگارکرن",summary:"د ئاستێ پێشکەفتیدا، ئەم تەنێ فێری «خوە بدە عەردی، خوە ڤەشێرە، خوە بگرە» (Drop, Cover, Hold On) نابین؛ بەلکی فێری ناسینا ستراکتۆرا ئاڤاهیان، پشکنینا زیانان پشتی عەردەهەژینێ، بنەمایێن ڕزگارکرنا بریندارێن بن کاڤلان و هاریکارییا تیمێن ڕزگارکرنێ ژی دبین.",blocks:[{heading:"ئاڤاهیسازی و سەلامەتییا ستراکتۆرێ",body:`• ئەو ئاڤاهییێن بێی ئەندازیارییا عەردەهەژینێ (Seismic Engineering) هاتینە ئاڤاکرن، مەترسیدارترن
• خالێن لاواز: قاتا ئێکێ یا ڤەکری (soft story)، ستوونێن کەڤن، بنیاتێ بێ کۆنکریت
• هەرێما کوردستانێ دکەڤیتە سەر پشتێنا چیایێن زاگرۆسێ کو ناڤچەیەکا چالاکا عەردەهەژینانە؛ لەوما عەردەهەژین ل ڤێرێ دشێن چێببن
• دەمێ هەژینێ: خوە بدە عەردی، خوە ل بن مێزەکا قایم ڤەشێرە و خوە بگرە (Drop, Cover, Hold On)، دوور ژ پەنجەران و ئامێرێن گران. نەچە بن دەرگەهی و باوەری ب «سێگۆشەیا ژیانێ» نەکە
• پشتی عەردەهەژینێ ئاڤاهیان بپشکنە: قلیشێن د دیواران دا، لاربوونا ستوونان، زیانا بنیاتی`,image:"media/images/seismic_building.png"},{heading:"ڕزگارکرن ژ بن کاڤلان (Urban SAR)",body:`• ڕزگارکرنا ژ بن کاڤلان کارێ تیمێن ڕاهێنان دیتی یێن بەرگرییا شارستانی (١١٥) یە. قوتابی چ جاران ناچنە سەر کاڤلان و ناچنە د ناڤ ئاڤاهییێن زیان لێ کەفتی دا، هەتا ب دەستکێش و کلاو ژی: کاڤل دشێن بلڤن و بکەڤن
• ژ جهەکێ سەلامەت گوهداری بکە و گازی بکە، جهێ دەنگی بزانە و ب تیمێ ڕزگارکرنێ بدە زانین
• خەلکێ دی ژ وێرێ دویر بێخە و ل دویڤ ڕێنمایێن تیمێ ڕزگارکرنێ بچە
• ئاگەهدار بە: غاز، کارەبا و ئاڤ دشێن ببنە مەترسی
• بۆ زانینێ: تیمێن ڕزگارکرنێ برینداران ب ڕەنگان پۆلبەندی دکەن (Triage): سوور = بلەز، زەرد = دشێت ل هیڤیێ بیت، کەسک = برینا سڤک، ڕەش = مری یان چ هیڤی بۆ ڕزگارکرنێ نەمای. قوتابی ڤی کاری ناکەن؛ ئەو ئاگەهدار دکەن و تەنێ دەمێ تیم داخواز دکەت هاریکارییێ دکەن`,image:"media/images/urban_sar.png"},{heading:"جانتایێ تەنگاڤییێ (Emergency Kit)",body:`• ئاڤ: نێزیکی ٤ لیتران بۆ هەر کەسەکی د ڕۆژێدا، ب کێمی بۆ ٣ ڕۆژان
• خوارن: خوارنا هشک و قوتیکری بۆ ٣ ڕۆژان
• دەرمان: کیتا هەوارهاتنا ئێکێ و دەرمانێن تایبەت یێن ئەندامێن خێزانێ
• ئامێر: چرایا دەستی، ڕادیۆ، باتری، فیکە
• بەلگەنامە: کۆپییێن ناسنامە و بەلگەنامێن گرنگ
• پارە: هندەک پارێ نەقد
• جلکێن گەرم و بەتانی`,image:"media/images/emergency_kit.png"}],examples:["پشکنینا ئاڤاهی: قلیش، ستوون، بنیات","ڕزگارکرن: ژ جهەکێ سەلامەت گوهداری بکە و ئاگەهدار بکە؛ چ جاران نەچە سەر کاڤلان","جانتایێ تەنگاڤیێ: ئاڤ + خوارن + دەرمان + چرا","کێلۆنا غازێ تەنێ بگرە ئەگەر بێهنا غازێ هات یان دەنگێ دەرچوونا وێ هات","ڕادیۆیێ بکار بینە بۆ گوهدارییا ئاگەهدارییان","Triage (تیمێن ڕزگارکرنێ): سوور، زەرد، کەسک، ڕەش","ئامادەباشی بۆ ٧٢ دەمژمێران","خالا کۆمبوونێ دیار بکە"],tips:["جانتایێ تەنگاڤیێ هەمیشە ئامادە بهێلە","دەمێ هەژینێ: خوە بدە عەردی، خوە ڤەشێرە، خوە بگرە (Drop, Cover, Hold On)","ئەسانسۆرێ بکار نەئینە","ل دەرڤە بمینە هەتا پسپۆڕ ئاڤاهی بپشکنن"],warnings:["پشتی عەردەهەژینا ئێکێ، هەمیشە ل هیڤییا هەژینێن پشتی وێ (aftershocks) بە. نەچە د ناڤ ئاڤاهییێن زیان لێ کەفتی دا! ئەگەر بێهنا غازێ هات یان دەنگێ دەرچوونا وێ هات، کێلۆنا غازێ بگرە و دەرکەڤە. ئاڤا بۆرییان بۆ ڤەخوارنێ بکار نەئینە هەتا نەهێتە پشکنین."],realCase:"د عەردەهەژینا تشرینا دووێ ٢٠١٧ دا، کو ل نێزیکی سنوورێ ئیران و عێراقێ چێبوو و زیان گەهاندە دەربەندیخان و هەلەبجە، خوەبەخشێن فێرکری هاریکارییا تیمێن ڕزگارکرنێ کرن. وان دزانی چەوا گوهدارییا دەنگێ بریندارێن بن کاڤلان بکەن و برینداران ب سیستەمێ Triage پۆلبەندی بکەن. زانین ژیانێ دپارێزیت!",video:"media/videos/lesson_earthquake_adv.mp4",game:{instruction:"پشتی عەردەهەژینێ، کیژ کار دروستن؟",items:[{text:"ئەگەر بێهنا غازێ هات، کێلۆنا غازێ بگرە و دەرکەڤە",emoji:"🔌",correct:!0},{text:"بچە د ناڤ ئاڤاهییێ زیان لێ کەفتی دا",emoji:"🏠",correct:!1},{text:"جهێ دەنگی ب تیمێ ڕزگارکرنێ بدە زانین",emoji:"📢",correct:!0},{text:"ئەسانسۆرێ بکار بینە",emoji:"🛗",correct:!1}]},activity:{prompt:"عەردەهەژینەکا ب هێزا ٦.٢ (ل سەر پیڤەرا ڕیختەری) هات. تو ل قوتابخانێ یی. ئاڤاهییەکێ نێزیک قلیشییە و دەنگێ کەسەکی ژ بن کاڤلان دهێت. دێ چ کەی؟",image:"media/images/activity_eq_adv.png",options:[{text:"ئێکسەر مامۆستای ئاگەهدار دکەم و گازی ١١٥ و ١٢٢ دکەین. جهێ دەنگی دیار دکەم و ب دەنگێ بلند دگەل برینداری دئاخڤم، بەلێ ناچمە د ناڤ ئاڤاهییێ قلیشی دا هەتا تیمێن ڕزگارکرنێ دگەهن",correct:!0},{text:"ب تەنێ دچمە د ناڤ ئاڤاهییێ قلیشی دا",correct:!1},{text:"چ تشتی ناکەم و تەنێ ل هیڤیێ دمینم",correct:!1},{text:"دڕەڤم بۆ مال",correct:!1}]},quiz:[{question:"Triage واتایا چ یە؟",options:[{text:"پۆلبەندیکرنا برینداران ل گۆر گرنگی و بلەزییا حالەتێ وان",correct:!0,feedback:"دروستە! تیمێن ڕزگارکرنێ: سوور = بلەز، زەرد = دشێت ل هیڤیێ بیت، کەسک = سڤک، ڕەش = مری یان چ هیڤی بۆ ڕزگارکرنێ نەمای."},{text:"هەوارهاتنا ئێکێ",correct:!1,feedback:"نەخێر!"},{text:"دەرکەفتن ژ ئاڤاهی",correct:!1,feedback:"نەخێر!"}]},{question:"پشتی عەردەهەژینێ، کەنگی کێلۆنا غازێ دگری؟",options:[{text:"تەنێ ئەگەر بێهنا غازێ هات یان دەنگێ دەرچوونا وێ هات",correct:!0,feedback:"دروستە! پاشان دەرکەڤە و ژ دەرڤە گازی ١١٥ بکە."},{text:"هەر جار، بەری هەر تشتەکی",correct:!1,feedback:"نەخێر! تەنێ ئەگەر نیشانێن دەرچوونا غازێ هەبن."},{text:"چ جاران",correct:!1,feedback:"نەخێر! ئەگەر بێهنا غازێ هات، دڤێت بهێتە گرتن."}]}]},{id:4,icon:"HeartPulse",accent:"#e11d48",title:"هەوارهاتنا ئێکێ: فشارا سنگی (CPR)",subtitle:"فشارا سنگی، هەناسەدان و AED",summary:"فشارا سنگی و هەناسەدان (CPR: Cardiopulmonary Resuscitation) ڕێکارەکا ڕزگارکرنا ژیانێ یە دەمێ دل و هەناسە ڕادوەستن. هەر کەسەک دڤێت فێری CPR ببیت. ل گۆر ئەنجومەنا دلی یا ئەمریکی (AHA)، هەر خولەکەکا بێی CPR و AED، شانسا مانێ ب ساخی نێزیکی ٧–١٠٪ کێم دبیت. ڕێزبەندییا C-A-B: ئێکەم فشارێن سنگی (Compressions)، پاشان ڤەکرنا ڕێکا هەوایێ (Airway)، پاشان هەناسە (Breathing).",blocks:[{heading:"CPR بۆ مەزنان (٣٠:٢)",body:`1. سەلامەتی: دەوروبەرێ خوە بپشکنە
2. بەرسڤدان: ملێن وی بهەژینە و ب دەنگێ بلند بپرسە «تو باشی؟»
3. گازی ١٢٢ (ئەمبوولانس) بکە و داخوازا ئامێرێ AED بکە؛ مۆبایلێ ل سەر بلندگۆیێ (speaker) دانە
4. هەناسەدانێ بپشکنە: د ١٠ چرکەیان یان کێمتر دا بەرێ خوە بدە سنگی
5. ٣٠ فشارێن سنگی: ل ناڤەڕاستا سنگی، ٥–٦ سم کوور، ١٠٠–١٢٠ فشار د خولەکێدا؛ پشتی هەر فشارەکێ بهێلە سنگ ب تەمامی ڤەگەڕیت
6. ٢ هەناسە: سەرێ وی بەرەڤ پاش ببە و چەنێ وی بلند بکە؛ هەر هەناسەکێ ب درێژاهییا ١ چرکێ فوو بکە هەتا سنگ بلند دبیت
7. ٣٠:٢ بەردەوام بکە هەتا ئەمبوولانس دگەهیت یان AED دهێت`,image:"media/images/cpr_steps.png"},{heading:"ئامێرێ AED (دیفیبریلاتۆر)",body:`• AED ئامێرەکێ ئۆتۆماتیکی یە کو ڕیتما دلی دپشکنیت و ئەگەر پێدڤی بوو شۆکەکا کارەبێ ددەت
• ئامێری ڤەکە و گوهداری ڕێنمایێن وی یێن دەنگی بکە
• پەدێن AED: ئێک ل لایێ ڕاستێ یێ سەرێ سنگی (ل بن هەستیێ ترقوێ)، یێ دی ل لایێ چەپێ یێ خوارێ سنگی (ل تەنشتێ)
• ئەگەر AED گۆت «شۆک پێدڤی یە»: کەس دەست ل برینداری نەدەت، پاشان دوگمێ شۆکێ فشار بدە
• پشتی شۆکێ، ئێکسەر CPR بۆ ٢ خولەک دەست پێ بکە
• AED هەر ٢ خولەک جارەکێ ڕیتما دلی دووبارە دپشکنیت`,image:"media/images/aed_use.png"},{heading:"CPR بۆ زارۆکان و زارۆکێن ساڤا",body:`• زارۆک (ژ ١ سالیێ هەتا بالغبوونێ): ئێک یان دوو دەستان بکار بینە، نێزیکی ٥ سم کوور (سێیەکا کووراهییا سنگی)؛ ٣٠:٢ ئەگەر تو ب تەنێ بی، ١٥:٢ ئەگەر دوو ڕزگارکەر هەبن
• زارۆکێ ساڤا (کێمتر ژ ١ سالی): دوو تلیێن مەزن و هەردوو دەست ل دەوری سنگی (two-thumb encircling)، یان بنێ ئێک دەستی؛ نێزیکی ٤ سم کوور (سێیەکا کووراهییا سنگی)؛ ٣٠:٢ ب تەنێ، ١٥:٢ ب دوو ڕزگارکەران. ڕێکا دوو تلیان ئێدی نایێتە فێرکرن (AHA 2025)
• هەناسە بۆ زارۆکێ ساڤا: دەڤێ خوە ل سەر دەڤ و دفنا وی پێکڤە دانە و ب هێدی فوو بکە
• ئەگەر تو ب تەنێ بی: ئەگەر مۆبایل دگەل تە هەبیت، ئێکسەر گازی ١٢٢ بکە ل سەر بلندگۆیێ و CPR دەست پێ بکە؛ ئەگەر مۆبایل نەبیت، ٢ خولەک CPR بکە، پاشان بچە گازی ١٢٢ بکە
• خەندقین (Choking): زارۆک: ٥ لێدان ل پشتێ + ٥ فشار ل سەر زکی (ل سەر ناڤکێ، گەلەک ل خوار هەستیێ سنگی)؛ زارۆکێ ساڤا: ٥ لێدان ل پشتێ (سەر ژ سنگی نزمتر) + ٥ فشار ل سەر سنگی؛ چ جاران فشارێ ل سەر زکێ ساڤای نەدە`,image:"media/images/cpr_child.png"}],examples:["٣٠ فشار + ٢ هەناسە = ١ خول","کووراهی: ٥–٦ سم (مەزن)، نێزیکی ٥ سم (زارۆک)، نێزیکی ٤ سم (ساڤا)","خێرایی: ١٠٠–١٢٠ فشار د خولەکێدا","ئێکەم جار: گازی ١٢٢ بکە و AED بخوازە","AED: پەدان ل سەر سنگی دانە و گوهداری ڕێنمایان بکە","هەر خولەکەکا بێی CPR: شانسا ژیانێ نێزیکی ٧–١٠٪ کێم دبیت","ساڤا: دوو تلیێن مەزن یان بنێ ئێک دەستی؛ دەڤ و دفن پێکڤە","ئەگەر دوو کەس هەبن: ئێک فشاران ددەت و یێ دی AED ئامادە دکەت"],tips:["هەمیشە سەلامەتییا خوە بێخە پێشیێ","٣٠:٢ ژبەر بکە","ب هێز و بلەز فشار بدە: ٥–٦ سم، ١٠٠–١٢٠ د خولەکێدا","د ناڤبەرا فشاران دا بهێلە سنگ ب تەمامی ڤەگەڕیت","ئەگەر AED بەردەست بوو، هندی زوو بکار بینە"],warnings:["زوو دەست ب CPR بکە! هەر خولەکەکا بێی CPR، شانسا ژیانێ نێزیکی ٧–١٠٪ کێم دبیت و پشتی ١٠ خولەکێن بێی CPR شانس گەلەک کێم دبیت. ژ شکەستنا پەراسووان نەترسە: د CPR یا دروست دا دبیت پەراسوو بشکێن، بەلێ ژیان گرنگترە!"],realCase:"ل سوپەرمارکێتەکێ ل دهۆکێ، زەلامەکێ ٥٥ سالی ژ نشکەکێ ڤە کەفت و دلێ وی ڕاوەستیا. قوتابییەکێ پۆلا ١١ێ کو فێری CPR بووی، ئێکسەر دەست ب فشارێن سنگی کر و هەڤالێ وی گازی ١٢٢ کر. ئەمبوولانس پشتی ٧ خولەک گەهشت و ئەو زەلام ساخ ما! بێی CPR، دبیت ئەو مربا.",video:"media/videos/lesson_cpr.mp4",game:{instruction:"هەنگاڤێن CPR ب ڕێزبەندی: یێن دروست هەلبژێرە:",items:[{text:"سەلامەتی → بەرسڤدان → ١٢٢ → فشار",emoji:"✅",correct:!0},{text:"فشار → هەناسە → ١٢٢",emoji:"❌",correct:!1},{text:"٣٠ فشار + ٢ هەناسە",emoji:"💓",correct:!0},{text:"١٠ فشار + ٥ هەناسە",emoji:"❌",correct:!1}]},activity:{prompt:"د قوتابخانێدا قوتابییەک ژ نشکەکێ ڤە کەفت، بەرسڤێ نادەت و هەناسەیا ئاسایی نادەت. تو ئێکەم کەسی ل وێرێ. دێ چ کەی؟",image:"media/images/activity_cpr.png",options:[{text:"سەلامەتییا جهی دپشکنم، بەرسڤدانا وی تاقی دکەم، گازی ١٢٢ دکەم و داخوازا AED دکەم، هەناسەدانێ دپشکنم و CPR ٣٠:٢ دەست پێ دکەم هەتا ئەمبوولانس دگەهیت",correct:!0},{text:"ئاڤێ دڕێژمە سەر ڕوویێ وی",correct:!1},{text:"دهێلم بلا بنڤیت",correct:!1},{text:"دڕەڤم",correct:!1}]},quiz:[{question:"ڕێژا فشاران و هەناسەیان د CPR یا مەزنان دا چەندە؟",options:[{text:"٣٠ فشار + ٢ هەناسە",correct:!0,feedback:"دروستە!"},{text:"١٥ + ٢",correct:!1,feedback:"نەخێر! ١٥:٢ بۆ زارۆک و ساڤایانە دەمێ دوو ڕزگارکەر هەبن."},{text:"١٠ + ١",correct:!1,feedback:"نەخێر!"}]},{question:"خێراییا فشارێن CPR چەندە؟",options:[{text:"١٠٠–١٢٠ د خولەکێدا",correct:!0,feedback:"دروستە!"},{text:"٦٠ د خولەکێدا",correct:!1,feedback:"گەلەک هێدی یە!"},{text:"٢٠٠ د خولەکێدا",correct:!1,feedback:"گەلەک بلەزە!"}]},{question:"هەر خولەکەکا بێی CPR، شانسا ژیانێ نێزیکی چەند کێم دبیت؟",options:[{text:"٧–١٠٪",correct:!0,feedback:"دروستە! (AHA)"},{text:"١٪",correct:!1,feedback:"نەخێر!"},{text:"٥٠٪",correct:!1,feedback:"نەخێر!"}]}]},{id:5,icon:"Biohazard",accent:"#9333ea",title:"ماددێن کیمیایی و مەترسیدار (HAZMAT)",subtitle:"ناسین و مامەلەکرن",summary:"HAZMAT (Hazardous Materials) ئەو ماددە نە یێن مەترسیدار: کیمیایی، بایۆلۆجی، تیشکدەر (ڕادیۆلۆجی) و ناڤکی (CBRN)، و ماددێن تەقینەر ژی. فێربوونا ناسینا وان و مامەلەکرنا دروست دگەل وان گرنگە بۆ قوتابیێن ناڤەندی و ئامادەیی.",blocks:[{heading:"GHS و هێمایێن ماددێن مەترسیدار",body:`GHS (Globally Harmonized System): سیستەمێ جیهانی یێ پۆلبەندیکرن و نیشانکرنا ماددێن کیمیایی. ٩ هێمایێن وی هەنە:
• کەللێ سەری و هەستی = ژەهراوی و کوژەک
• ئاگر = سووتەنی
• ئاگر ل سەر بازنەیێ = ئۆکسیدکەر
• بۆمبا تەقیای = تەقینەر
• دلۆپ ل سەر دەستی و کانزای = داخوەر (Corrosive)
• بوتلا غازێ = غازا ب فشار
• نیشانا (!) = ئێشاندن و زیانا سڤک
• لەشێ مرۆڤی ب ستێرەکێ ل سەر سنگی = مەترسییا گران بۆ تەندروستیێ (وەکی شێرپەنجە)
• ماسی و دار = مەترسی بۆ ژینگەهێ

GHS هێمایا تیشکدەر (ڕادیۆئاکتیڤ) تێدا نینە؛ ئەو هێما د ڕێنمایێن UN یێن ڤەگوهاستنا ماددێن مەترسیدار دا (پۆلا ٧) هەیە.

لۆزنا NFPA 704 (٤ ڕەنگ):
• سوور = سووتەنی (٠–٤)
• شین = تەندروستی (٠–٤)
• زەرد = نەجێگیری (٠–٤)
• سپی = مەترسیێن تایبەت: OX (ئۆکسیدکەر)، W ب هێلەکێ ل سەر (ئاڤێ بکار نەئینە)، SA (غازا خەندقێنەر)`,image:"media/images/ghs_symbols.png"},{heading:"SDS و پاراستنا کەسی (PPE)",body:`SDS (Safety Data Sheet): پەڕەیا زانیارییێن سەلامەتییێ یە و ١٦ پشکێن زانیارییان دەربارەی هەر ماددەیەکا کیمیایی تێدا هەنە:
• پشکا ٢: ناسینا مەترسییان
• پشکا ٤: هەوارهاتنا ئێکێ
• پشکا ٥: ئاگرکوژاندن
• پشکا ٨: کەرەستێن پاراستنا کەسی (PPE)

ئاستێن PPE:
• A: جلکێن کیمیایی یێن تەمام داخستی + ئامێرێ هەناسەدانێ یێ سەربخوە (SCBA)
• B: جلکێن بەرگرییا کیمیایی + SCBA
• C: جلکێن بەرگرییا کیمیایی + ماسکا فلتەری
• D: جلکێن کاری یێن ئاسایی + دەستکێش و چاڤیلک`,image:"media/images/sds_ppe.png"},{heading:"پاقژکرنەڤە (Decontamination) و ڕێکار",body:`ئەگەر ماددەکا مەترسیدار بەلاڤ بوو:
1. ئاگەهدار بکە: گازی ١١٥ بکە (ئەگەر بریندار هەبن، ١٢٢ ژی)
2. دەرکەڤە: بچە ل وی لایێ کو با ژێ دهێت (upwind)، داکو با غاز و تۆزێ بەرەڤ تە نەئینیت
3. ب کێمی ١٠٠ مەتران دوور بکەڤە
4. دەست لێ نەدە و بێهن نەکە
5. پاقژکرنەڤە: جلکێن پیسبووی ژ بەر خوە بکە، پێست و چاڤان ب ئاڤا بەردەوام ١٥–٢٠ خولەک بشۆ
6. ل هیڤییا تیمێ HAZMAT یێ بەرگرییا شارستانی بە`,image:"media/images/decontamination.png"}],examples:["کەللێ سەری = ژەهراوی","ئاگر = سووتەنی","دلۆپ ل سەر دەستی = داخوەر","بۆمبا تەقیای = تەقینەر","SDS: ١٦ پشک","ئاستێن PPE: A، B، C، D","بچە ل وی لایێ کو با ژێ دهێت (upwind)","ب کێمی ١٠٠ مەتران دوور بکەڤە"],tips:["٩ هێمایێن GHS فێر ببە","SDS بخوینە بەری بکارئینانا هەر ماددەیەکێ","PPE یا گونجای بکار بینە","بچە ل وی لایێ کو با ژێ دهێت"],warnings:["چ جاران دەست ل ماددەکا کیمیایی یا نەناس نەدە، بێهن نەکە و تاقی نەکە! هەمیشە بچە ل وی لایێ کو با ژێ دهێت (upwind) و ب کێمی ١٠٠ مەتران دوور بمینە. گازی ١١٥ بکە دا تیمێ HAZMAT بهێت!"],realCase:"ل کارگەهەکێ ل سلێمانیێ، بڕەکا ئەسیدێ ڕژیا. کارمەندەکێ فێرکری ئێکسەر ئاگەهداری دا، هەمی کارمەند برنە وی لایێ کو با ژێ دهات و گازی ١١٥ کر دا تیمێ HAZMAT بهێت. کەس بریندار نەبوو!",video:"media/videos/lesson_hazmat.mp4",game:{instruction:"هەر هێمایەکێ ب واتا وێ ڤە گرێبدە؛ یێن دروست هەلبژێرە:",items:[{text:"کەللێ سەری و هەستی = ژەهراوی",emoji:"☠️",correct:!0},{text:"ئاگر = ماددەیەکا بێ مەترسی",emoji:"🔥",correct:!1},{text:"هێمایا داخوەر = بێ مەترسی بۆ پێستی",emoji:"⚗️",correct:!1},{text:"نیشانا (!) = مەترسی بۆ تەندروستیێ (ئێشاندن)",emoji:"⚠️",correct:!0}]},activity:{prompt:"د تاقیگەهێدا شووشەکا ئەسیدێ شکا و ڕژیا. دێ چ کەی؟",image:"media/images/activity_hazmat.png",options:[{text:"هەمییان ئاگەهدار دکەم، ژ تاقیگەهێ بەرەڤ وی لایێ کو با ژێ دهێت دەردکەڤین، مامۆستای ئاگەهدار دکەم و گازی ١١٥ دکەین، و دەست لێ نادەم",correct:!0},{text:"ب دەستمالەکێ پاقژ دکەم",correct:!1},{text:"ئاڤێ دڕێژمە سەر",correct:!1},{text:"چ تشتی ناکەم",correct:!1}]},quiz:[{question:"د لۆزنا NFPA دا، ڕەنگێ سوور واتایا چ یە؟",options:[{text:"سووتەنی",correct:!0,feedback:"دروستە!"},{text:"تەندروستی",correct:!1,feedback:"ئەو شینە!"},{text:"نەجێگیری",correct:!1,feedback:"ئەو زەردە!"}]},{question:"بۆچی دچینە وی لایێ کو با ژێ دهێت (upwind)؟",options:[{text:"داکو با غاز و تۆزێ بەرەڤ مە نەئینیت",correct:!0,feedback:"دروستە!"},{text:"داکو زووتر بگەهینە مال",correct:!1,feedback:"نەخێر!"},{text:"چ جوداهی نینە",correct:!1,feedback:"نەخێر!"}]}]},{id:6,icon:"Waves",accent:"#0891b2",title:"لافاو و کارەسات: پلاندانان",subtitle:"ئاگەهدارکرن و ئامادەباشی",summary:"لافاو و کارەساتێن سروشتی پێدڤی ب پلاندانانەکا پێشوەخت هەنە. د ئاستێ ئامادەییدا، ئەم فێری سیستەمێن ئاگەهدارکرنێ، پلانا تەنگاڤیێ یا خێزانی و ڕۆلێ قوتابیان د تیمێن سەلامەتییێ دا دبین.",blocks:[{heading:"سیستەمێن ئاگەهدارکرنێ",body:`• EWS (Early Warning System): سیستەمێ ئاگەهدارکرنا پێشوەخت بەری کارەساتێ
• ئاستێن ئاگەهدارکرنێ:
کەسک = ئاسایی
زەرد = هشیار بە
پرتەقالی = ئامادە بە
سوور = تەنگاڤی، دەرکەڤە
• پیڤەرێ لافاوێ (flood gauge): بلندییا ئاڤێ نیشان ددەت
• ئاگەهدارییێن سەقای: ب ڕێکا ڕادیۆ، تەلەفزیۆن و مۆبایلێ`,image:"media/images/ews_system.png"},{heading:"پلانا تەنگاڤیێ یا خێزانی",body:`• خالێن کۆمبوونێ: ٢ خال (ئێک نێزیک و ئێک دوور)
• ڕێکێن دەرکەفتنێ: ٢ ڕێک ژ مالێ
• پەیوەندی: ژمارێن تەلەفۆنا هەمی ئەندامێن خێزانێ
• جانتایێ تەنگاڤیێ: بۆ ٧٢ دەمژمێران (ئاڤ: نێزیکی ٤ لیتران بۆ هەر کەسەکی د ڕۆژێدا)
• بەلگەنامە: کۆپی ل جهەکێ سەلامەت و دوور ژ ئاڤێ
• ڕاهێنان: پلانێ ب کێمی سالێ دوو جاران دگەل خێزانێ تاقی بکە`,image:"media/images/family_plan.png"},{heading:"ڕۆلێ قوتابی د سەلامەتییێ دا",body:`• CERT (Community Emergency Response Team): تیمێن خوەبەخش یێن جڤاکی بۆ هاریکارییێ ل دەمێ تەنگاڤیان
• قوتابیێن فێرکری دشێن ببنە هاریکارێن دەستپێکێ
• ڕۆل: ئاگەهدارکرن، هەوارهاتنا ئێکێ، هاریکارییا زیانلێکەفتیان
• هەماهەنگی دگەل ١١٥ و لایەنێن پەیوەندیدار
• ناسینا مەترسیێن دەوروبەری`,image:"media/images/cert_team.png"}],examples:["سوور = تەنگاڤی، دەرکەڤە!","زەرد = هشیار بە","جانتایێ ٧٢ دەمژمێری","ژمارێن هەمی ئەندامێن خێزانێ","٢ خالێن کۆمبوونێ","٢ ڕێکێن دەرکەفتنێ","CERT: تیمێن هاریکارییا جڤاکی","ڕادیۆ بۆ گوهدارییا ئاگەهدارییان"],tips:["پلانا خێزانی دروست بکە","جانتایێ تەنگاڤیێ ئامادە بهێلە","ب کێمی سالێ دوو جاران ڕاهێنانێ ل سەر پلانێ بکە"],warnings:["لافاو ژ مەترسیدارترین کارەساتێن سروشتی یە! تەنێ ١٥ سم ژ ئاڤا لافاوێ یا دلڤیت دشێت مرۆڤی بێخیتە عەردی، و ٣٠ سم دشێت ترمبێلەکێ ببەت. چ جاران ب پێیان یان ب ترمبێلێ نەچە د ناڤ ئاڤا لافاوێ دا!"],realCase:"خێزانەکێ ل زاخۆ پلانا تەنگاڤیێ هەبوو. دەمێ لافاو هاتی، ئەو د ٥ خولەکاندا دەرکەفتن و ل خالا کۆمبوونێ کۆم بوون. ئەو خێزانێن پلان نەبووین، زیانێن مەزن ب وان کەفتن.",video:"media/videos/lesson_flood_adv.mp4",game:{instruction:"ئاڤا لافاوێ یا دلڤیت چەند مەترسیدارە؟ یێن دروست هەلبژێرە:",items:[{text:"١٥ سم دشێت مرۆڤی بێخیتە عەردی",emoji:"🚶",correct:!0},{text:"ئاڤا کێم چ مەترسی نینە",emoji:"🤷",correct:!1},{text:"٣٠ سم دشێت ترمبێلەکێ ببەت",emoji:"🚗",correct:!0},{text:"دشێی ب ترمبێلێ د ناڤ ئاڤێ ڕا دەرباز ببی",emoji:"✅",correct:!1}]},activity:{prompt:"ئاگەهدارییا سوور بۆ لافاوێ ل دەوروبەرێ مالا تە هات. ٢ دەمژمێر ماینە هەتا ئاڤ بگەهیتە وێرێ. دێ چ کەی؟",image:"media/images/activity_flood_adv.png",options:[{text:"پلانا خێزانی دەست پێ دکەم، جانتایێ تەنگاڤیێ هەلدگرم، ئەندامێن خێزانێ ئاگەهدار دکەم و دچینە خالا کۆمبوونێ ل جهەکێ بلند",correct:!0},{text:"تەنێ ل هیڤیێ دمینم",correct:!1},{text:"ل مالێ دمینم",correct:!1},{text:"دچمە سوپەرمارکێتێ",correct:!1}]},quiz:[{question:"EWS واتایا چ یە؟",options:[{text:"سیستەمێ ئاگەهدارکرنا پێشوەخت بەری کارەساتێ",correct:!0,feedback:"دروستە!"},{text:"ئامێرەکێ سەلامەتییێ",correct:!1,feedback:"نەخێر!"},{text:"جۆرەکێ تەمرینکێ",correct:!1,feedback:"نەخێر!"}]}]},{id:7,icon:"Zap",accent:"#ca8a04",title:"کارەبا: ڤۆلتاژا بلند",subtitle:"مەترسی و ڕزگارکرنا سەلامەت",summary:"کارەبا ب ڤۆلتاژا بلند (High Voltage) دشێت مرۆڤی بکوژیت و سووتنێن کوور چێبکەت. فێربوونا ناسینا مەترسییان و ڕێکێن ڕزگارکرنا سەلامەت گەلەک گرنگە.",blocks:[{heading:"مەترسییا ڤۆلتاژا بلند",body:`• ڤۆلتاژا مالان: ٢٢٠ ڤۆلت؛ ئەڤە ژی دشێت بکوژیت!
• ڤۆلتاژا بلند: ژ ١١ هەتا ٤٠٠ کیلۆڤۆلت (kV) د تەلێن ڤەگوهاستنا کارەبێ دا
• ئەو تەزوو (ئامپێر) یێ د ناڤ لەشی ڕا دچیت مرۆڤی دکوژیت؛ ڤۆلتاژا بلند تەزوویەکێ مەزنتر د لەشی ڕا دبەت. تەنێ ٠.١ ئامپێر (١٠٠ میلی ئامپێر) ب ڕێکا دلی دشێت بکوژیت
• کارەبا ب ڤۆلتاژا بلند دشێت ب ڕێکا هەوایێ بپەڕیت (Arc) بێی کو تو دەست لێ بدەی؛ لەوما ب کێمی ١٠ مەتران دوور بمینە
• سووتنا کارەبێ کوورە و دبیت ژ دەرڤە نەهێتە دیتن`,image:"media/images/high_voltage.png"},{heading:"ڕزگارکرنا بریندارێن کارەبێ",body:`1. دەست ل برینداری نەدە هەتا کارەبا نەهێتە بڕین!
2. ئەگەر ڤۆلتاژا بلند بوو: ب کێمی ١٠ مەتران دوور بمینە و گازی ١١٥ بکە؛ تەنێ تیمێن پسپۆڕ دشێن کارەبێ ببڕن
3. کارەبا مالێ: ژ فیوزێ، برێکەری (breaker) یان سویچێ سەرەکی ببڕە
4. ئەگەر نەشیای کارەبا مالێ ببڕی: ل سەر تشتەکێ هشک ڕاوەستە و ب تشتەکێ نەگەهینەر (دارا هشک، پلاستیک) برینداری ژ سەرچاڤەیا کارەبێ دوور بێخە. ئەڤێ بۆ ڤۆلتاژا بلند چ جاران نەکە!
5. گازی ١٢٢ بکە؛ ئەگەر برینداری هەناسە نەدا، CPR دەست پێ بکە
6. سووتنان بپشکنە (جهێ چوونا کارەبێ بۆ ناڤ لەشی و جهێ دەرکەفتنا وێ) و پشتی بڕینا کارەبێ ب ئاڤا فێنک یا ڕەوان ٢٠ خولەک سار بکە`,image:"media/images/electric_rescue.png"},{heading:"خوەپاراستن",body:`• نێزیکی ترانسفۆرماتۆر و تەلێن بلند نەبە
• تەلا کارەبێ یا کەفتییە سەر عەردی = مەترسی! ب کێمی ١٠ مەتران دوور بە
• ئەگەر د ناڤ ترمبێلێدا بووی و تەل کەفتە سەر: د ناڤدا بمینە و گازی ١١٥ بکە. ئەگەر ترمبێل ئاگر گرت، ب هەردوو پێیان پێکڤە ژێ باز بدە، بێی کو د ئێک دەمدا دەست ل ترمبێلێ و عەردی بدەی
• ئەگەر نێزیکی تەلەکا کەفتی بووی: ب هەنگاڤێن گەلەک بچووک و پێیێن پێکڤە (shuffle) دوور بکەڤە، بێی پێیان ژ عەردی بلند بکەی
• دەمێ برووسک و بارانێ: ل ناڤ ئاڤاهییەکی بمینە`,image:"media/images/electric_prevention.png"}],examples:["٠.١ ئامپێر ب ڕێکا دلی دشێت بکوژیت","ڤۆلتاژا بلند: ب کێمی ١٠ مەتران دوور بمینە","ئێکەم جار کارەبێ ببڕە","تشتەکێ نەگەهینەر بکار بینە (تەنێ بۆ کارەبا مالێ)","ئەگەر تەل کەفتە سەر ترمبێلێ، د ناڤدا بمینە","هەنگاڤێن بچووک (Shuffle step): بێی پێیان ژ عەردی بلند بکەی","CPR ئەگەر پێدڤی بوو","گازی ١٢٢ بکە؛ بۆ تەلێن کەفتی ١١٥"],tips:["ئێکەم جار کارەبێ ببڕە","دەست ل برینداری نەدە هەتا کارەبا نەهێتە بڕین","تشتەکێ نەگەهینەر بکار بینە","گازی ١٢٢ بکە بۆ برینداری و ١١٥ بۆ تەلا کەفتی"],warnings:["چ جاران دەست ل بریندارێ کارەبێ نەدە هەتا کارەبا نەهێتە بڕین! کارەبا دێ د لەشێ تە ژی ڕا دەرباز بیت و هەردوو دێ ببنە قوربانی. ژ ڤۆلتاژا بلند ب کێمی ١٠ مەتران دوور بمینە!"],realCase:"ل گوندەکێ دهۆکێ، پشتی بایەکێ ب هێز، تەلەکا کارەبێ یا ڤۆلتاژا بلند کەفتە سەر عەردی. گەنجەکێ ١٦ سالی یێ فێرکری دزانی کو نابیت نێزیک ببیت. وی هەمی خەلک ئاگەهدار کرن کو دوور بکەڤن و گازی ١١٥ کر. تیمێن چاککرنێ هاتن و مەترسی نەهێلا.",video:"media/videos/lesson_highvolt.mp4",game:{instruction:"دەمێ کارەبا ل کەسەکی ددەت، ئێکەم کارێن دروست کیژن؟",items:[{text:"کارەبێ ببڕە",emoji:"🔌",correct:!0},{text:"دەست ل برینداری بدە",emoji:"🤚",correct:!1},{text:"گازی ١٢٢ بکە",emoji:"📞",correct:!0},{text:"ب پارچە ئاسنەکی ژ کارەبێ دوور بێخە",emoji:"🔧",correct:!1}]},activity:{prompt:"هەڤالەکێ تە د تاقیگەهێدا کارەبێ لێ دا و کەفت. وایەر هێشتا ب لەشێ وی ڤە یە. دێ چ کەی؟",image:"media/images/activity_electric.png",options:[{text:"ئێکەم جار فیوز یان برێکەرێ کارەبێ دبڕم، پاشان ئەگەر پێدڤی بوو ب تشتەکێ نەگەهینەر وایەری ژ وی دوور دئێخم بێی دەست ل لەشێ وی بدەم، و گازی ١٢٢ دکەم؛ ئەگەر هەناسە نەدا، CPR دەست پێ دکەم",correct:!0},{text:"ب دەستان وی دکێشم",correct:!1},{text:"ئاڤێ دڕێژمە سەر",correct:!1},{text:"چ تشتی ناکەم",correct:!1}]},quiz:[{question:"چەند تەزوو (ئامپێر) ب ڕێکا دلی دشێت مرۆڤی بکوژیت؟",options:[{text:"٠.١ ئامپێر",correct:!0,feedback:"دروستە! تەنێ ١٠٠ میلی ئامپێر."},{text:"١٠٠ ئامپێر",correct:!1,feedback:"گەلەک کێمتر ژ ڤێ ژی دکوژیت!"},{text:"١٠٠٠ ئامپێر",correct:!1,feedback:"نەخێر!"}]}]},{id:8,icon:"Fuel",accent:"#059669",title:"دەرچوونا غازێ و تەقین",subtitle:"غازا سروشتی و غازا بوتلێ (LPG)",summary:"غازا سروشتی (Natural Gas) و غازا بوتلێ (LPG) هەردوو سووتەنی و تەقینەرن. ئەڤ وانە تایبەتمەندییێن فیزیکی یێن غازێ و ڕێکارێن پێشکەفتی یێن خوەپاراستنێ نیشان ددەت.",blocks:[{heading:"غازا سروشتی بەرامبەر LPG",body:`• غازا سروشتی (پترییا وێ میتان/Methane): ژ هەوایێ سڤکترە و بەرەڤ سەری دچیت (ب بۆریان دهێت)
• LPG (پرۆپان و بوتان): ژ هەوایێ گرانترە و ل خوارێ، نێزیکی عەردی کۆم دبیت (د بوتلان دا)
• LEL (ئاستێ نزمترین یێ تەقینێ): کێمترین ڕێژا غازێ د هەوایێ دا کو دشێت ئاگر بگریت یان بتەقیت. UEL (ئاستێ بلندترین): ژ ڤێ ڕێژێ زێدەتر، تێکەل ئاگر ناگریت
• غازا سروشتی (میتان): LEL نێزیکی ٥٪، UEL نێزیکی ١٥٪
• LPG (پرۆپان): LEL نێزیکی ٢.١٪، UEL نێزیکی ٩.٥٪؛ لەوما ڕێژەیەکا کێمتر ژ LPG دشێت بتەقیت
• مێرکاپتان: بێهنەکا تایبەت کو بۆ ناسینێ دهێتە زێدەکرن، چونکی غاز ب خوە بێ بێهنە`,image:"media/images/gas_types.png"},{heading:"ناسین و ڕێکار",body:`• بێهن: بێهنا هێکێن گەنی (مێرکاپتان)
• دەنگ: دەنگێ فشەفشا غازێ ژ بۆری یان بوتلێ
• نیشانێن دی: هشکبوونا گیا و داران نێزیکی بۆرییا بن عەردی، یان قەشا و سارییا جهێ دەرچوونا LPG

ڕێکار:
1. چ ئاگران هەلنەکە (شەخات، چەقماخ)! سویچێن کارەبێ ڤەنەکە و نەگرە!
2. مۆبایلێ ل ناڤ جهی بکار نەئینە
3. پەنجەر و دەرگەهان ڤەکە
4. ئەگەر ب سەلامەتی بشێی، کێلۆنا غازێ بگرە
5. دەرکەڤە
6. ژ دەرڤەی ئاڤاهی گازی ١١٥ بکە و لایەنێ غازێ ئاگەهدار بکە`,image:"media/images/gas_procedure.png"},{heading:"تەقین و خوەپاراستن",body:`• BLEVE (Boiling Liquid Expanding Vapour Explosion): تەقینەکا مەزنە کو دەمێ بوتلا LPG د ناڤ ئاگری دا گەرم دبیت و دتەقیت چێدبیت
• ئاگر + غاز = تەقین، ئەگەر ڕێژا غازێ د ناڤبەرا LEL و UEL دا بیت

خوەپاراستن:
• ئامێرێ ئاگەهدارکرنا غازێ (gas detector) ل مالێ دانە
• بۆریان ب ئاڤا سابوونێ تاقی بکە (bubble test)؛ چ جاران ب ئاگری تاقی نەکە
• سۆبە و ئامێرێن غازێ د ژوورا نڤستنێدا بکار نەئینە
• دەمێ بکار نائینی، کێلۆنا غازێ بگرە`,image:"media/images/gas_prevention.png"}],examples:["غازا سروشتی بەرەڤ سەری دچیت / LPG ل خوارێ کۆم دبیت","بێهنا هێکێن گەنی = غاز","شەخاتێ و چەقماخێ هەلنەکە!","پەنجەران ڤەکە","کێلۆنا غازێ بگرە","ژ دەرڤە گازی ١١٥ بکە","ئامێرێ ئاگەهدارکرنا غازێ دانە","تاقیکرنا ئاڤا سابوونێ (bubble test) بۆ بۆریان"],tips:["ئامێرێ ئاگەهدارکرنا غازێ دانە","بۆریان ب ڕێک و پێک تاقی بکە","سۆبێن غازێ د ژوورا نڤستنێدا بکار نەئینە","پشتی بکارئینانێ هەمیشە کێلۆنا غازێ بگرە"],warnings:["مۆبایلێ د ناڤ ژوورەکا تژی غاز دا بکار نەئینە! مۆبایل ژی دشێت پریسکەکێ دەربێخیت و تەقین چێببیت. ژ دەرڤەی ئاڤاهی گازی ١١٥ بکە."],realCase:"ل شۆقەیەکێ ل دهۆکێ، تەقینەکا غازێ چێبوو. ڤەکۆلینێ دیار کر کو غاز دەرچووبوو و ڤەکرنا سویچێ چرایێ بوو ئەگەرێ تەقینێ. ئەگەر ئامێرێ ئاگەهدارکرنا غازێ هەبا، دا بەری تەقینێ ئاگەهدار کەت.",video:"media/videos/lesson_gas_adv.mp4",game:{instruction:"غازا LPG (بوتل) بەرەڤ کیڤە دچیت؟",items:[{text:"بەرەڤ خوارێ (ژ هەوایێ گرانترە)",emoji:"⬇️",correct:!0},{text:"بەرەڤ سەری",emoji:"⬆️",correct:!1},{text:"ب وەکهەڤی ل هەمی جهان بەلاڤ دبیت",emoji:"💨",correct:!1},{text:"بێ بێهنە و نایێتە ناسین",emoji:"👃",correct:!1}]},activity:{prompt:"تو دگەهیە مال و بێهنا غازێ دهێت. چرا هەلکرییە و مۆبایل د دەستێ تە دایە. دێ چ کەی؟",image:"media/images/activity_gas_adv.png",options:[{text:"مۆبایلێ ل ناڤدا بکار نائینم و دەست ل سویچێ چرایێ نادەم، پەنجەران ڤەدکەم، ئەگەر ب سەلامەتی بشێم کێلۆنا غازێ دگرم، دەردکەڤم و ژ دەرڤە گازی ١١٥ دکەم",correct:!0},{text:"دەست ل سویچێ چرایێ ددەم",correct:!1},{text:"ل ناڤ مالێ مۆبایلێ بکار دئینم",correct:!1},{text:"ل وێرێ دمینم",correct:!1}]},quiz:[{question:"LEL واتایا چ یە؟",options:[{text:"کێمترین ڕێژا غازێ د هەوایێ دا کو دشێت بتەقیت (بۆ غازا سروشتی نێزیکی ٥٪)",correct:!0,feedback:"دروستە! بۆ LPG (پرۆپان) نێزیکی ٢.١٪ یە."},{text:"جۆرەکێ غازێ",correct:!1,feedback:"نەخێر!"},{text:"جۆرەکێ تەقینێ",correct:!1,feedback:"نەخێر! LEL ئاستەکە، نە تەقین."}]}]},{id:9,icon:"DoorOpen",accent:"#7c3aed",title:"پلانا دەرکەفتنا سەلامەت",subtitle:"ICS و ڕێڤەبرنا تەنگاڤیان",summary:"ICS (Incident Command System) سیستەمێ فەرماندەییا ڕووداوان، سیستەمەکێ نێڤدەولەتی یە بۆ ڕێڤەبرنا تەنگاڤیان. د ئاستێ ئامادەییدا، قوتابی فێری ڕۆلێن ICS و پلاندانانا پێشکەفتی یا دەرکەفتنێ دبن.",blocks:[{heading:"ICS: سیستەمێ فەرماندەییێ",body:`ICS ب ٥ پشکێن سەرەکی کار دکەت:
1. فەرماندەیی (Command): بڕیاردەر؛ ئێک کەس سەرپەرشتیا هەمی کاران دکەت
2. کارێن مەیدانی (Operations): تیمێن کاری (ئاگرکوژاندن، ڕزگارکرن، هەوارهاتنا ئێکێ)
3. پلاندانان (Planning): کۆمکرنا زانیارییان و دانانا پلانێ
4. لۆجستی (Logistics): کەرەستە، ڤەگوهاستن، خوارن، جهـ
5. دارایی و کارگێری (Finance/Admin): تۆمارکرن و خەرجی

ل قوتابخانێ:
• ڕێڤەبەر یان مامۆستایێ سەرەکی = فەرماندە
• مامۆستا = تیمێن کارێ مەیدانی
• قوتابیێن فێرکری = هاریکار`,image:"media/images/ics_structure.png"},{heading:"پلانا دەرکەفتنێ یا پێشکەفتی",body:`• ناسینا ئاڤاهی: هەمی دەرگەهـ، پلەکان و دەرکەفتنێن تەنگاڤیێ
• ناسینا مەترسییان: غاز، کارەبا، ماددێن کیمیایی
• ڕێکا سەرەکی + ڕێکا جێگر
• خالا کۆمبوونێ: سەرەکی + جێگر
• ژمارتنا کەسان (headcount)
• بەرپرسێن دیارکری: کێ ئاگەهدار دکەت، کێ دەرگەهان ڤەدکەت، کێ دژمێریت
• کەسێن خودان پێدڤییێن تایبەت: بریندار، کەسێن ب کورسییا تەکەردار، نابینا
• ڕاگەهاندن: مێگافۆن، زەنگ، سایرین
• دەرگەهێن دەرکەفتنێ دڤێت ژ ناڤدا بێی کلیل ڤەببن`,image:"media/images/evac_plan_adv.png"},{heading:"ڕاهێنانا دروست",body:`• ڕاگەهاندن + دەرکەفتن + ژمارتن + ڕاپۆرت
• هەنگاڤێن ڕاهێنانێ:
1. لێدانا زەنگێ یان سایرینێ
2. ڕاگرتنا هەمی کاران
3. ب ڕێزبەندی بەرەڤ نێزیکترین دەرگەهی
4. پلەکان (ئەسانسۆرێ بکار نەئینە!)
5. خالا کۆمبوونێ
6. ژمارتنا کەسان و ڕاپۆرت
7. هەتا فەرمانا «سەلامەتە» نەهێتە دان، نەزڤڕە ژوور
• دەمێ دەرکەفتنێ تۆمار بکە و د هەر ڕاهێنانەکێ دا کێمتر بکە
• تۆمارا ڕاهێنانان بپارێزە`,image:"media/images/drill_procedure.png"}],examples:["ICS: فەرماندەیی + کارێن مەیدانی + پلاندانان + لۆجستی + دارایی","٢ ڕێکێن دەرکەفتنێ + ٢ خالێن کۆمبوونێ","دەمێ دەرکەفتنێ تۆمار بکە","ژمارتنا کەسان (headcount)","زەنگ یان سایرین = ئاگەهدارکرن","تەنێ پلەکان!","بەرپرسێن تایبەت دیار بکە","تۆمارا ڕاهێنانان"],tips:["ICS فێر ببە","ب ڕێک و پێک ڕاهێنانێن دەرکەفتنێ بکە","ژمارتنا کەسان گەلەک گرنگە","بەرپرسێن تایبەت دیار بکە"],warnings:["چ جاران ل دەمێ تەنگاڤیان ئەسانسۆرێ بکار نەئینە! ئەسانسۆر دشێت د ناڤبەرا قاتان دا ڕاوەستیت و تو تێدا بمینی. هەمیشە پلەکانان بکار بینە!"],realCase:"ل قوتابخانەکێ ل هەولێرێ، مامۆستایەکی ICS فێر بووبوو. دەمێ ئاگرەکێ ڕاستەقینە چێبووی، وی وەک فەرماندە ڕۆل دابەش کرن: تیمەک بۆ ئاگرکوژاندنێ ب تەمرینکان، تیمەک بۆ دەرئێخستنا قوتابیان و تیمەک بۆ ژمارتنێ. د ٤ خولەکاندا ٤٠٠ قوتابی دەرکەفتن و کەس بریندار نەبوو!",video:"media/videos/lesson_ics.mp4",game:{instruction:"د سیستەمێ ICS دا، کیژ گۆتن دروستن؟",items:[{text:"فەرماندەیی (Command) بڕیاران ددەت",emoji:"👨‍✈️",correct:!0},{text:"لۆجستی بڕیاردەرێ سەرەکی یە",emoji:"📦",correct:!1},{text:"کارێن مەیدانی (Operations) کارێ ل جهی دکەن",emoji:"⚙️",correct:!0},{text:"هەر کەسەک ب سەرێ خوە بڕیار ددەت",emoji:"🤷",correct:!1}]},activity:{prompt:"تو بەرپرسێ سەلامەتییا پۆلا خوە یی. زەنگا ئاگەهدارکرنێ لێدا. ٣ قوتابیێن خودان پێدڤییێن تایبەت د پۆلێ دا هەنە. دێ چ کەی؟",image:"media/images/activity_ics.png",options:[{text:"ئێکەم جار هاریکارییا قوتابیێن خودان پێدڤییێن تایبەت دکەم، ب ڕێزبەندی بەرەڤ پلەکانان دچین، ل خالا کۆمبوونێ کەسان دژمێرم و ڕاپۆرتێ ددەمە مامۆستای",correct:!0},{text:"ب لەز ب تەنێ دڕەڤم",correct:!1},{text:"ل پۆلێ ل هیڤیێ دمینم",correct:!1},{text:"ئەسانسۆرێ بکار دئینم",correct:!1}]},quiz:[{question:"ICS چەند پشکێن سەرەکی هەنە؟",options:[{text:"٥",correct:!0,feedback:"دروستە! Command، Operations، Planning، Logistics، Finance/Admin."},{text:"٣",correct:!1,feedback:"نەخێر!"},{text:"١٠",correct:!1,feedback:"نەخێر!"}]},{question:"د ڕاهێنانێدا، پشتی گەهشتنا خالا کۆمبوونێ چ دهێتە کرن؟",options:[{text:"ژمارتنا کەسان (headcount) و ڕاپۆرتدان",correct:!0,feedback:"دروستە! داکو بزانین کەس د ناڤ ئاڤاهی دا نەمایە."},{text:"ئێکسەر ڤەگەڕیان بۆ پۆلێ",correct:!1,feedback:"نەخێر! هەتا فەرمانا «سەلامەتە» نەهێتە دان، نەزڤڕە."},{text:"هەر قوتابییەک دچیتە مالا خوە",correct:!1,feedback:"نەخێر! دڤێت هەمی بهێنە ژمارتن."}]}]},{id:10,icon:"Droplets",accent:"#dc2626",title:"خوینبەربوون و شکەستنا هەستیان",subtitle:"هەوارهاتنا ئێکێ یا پێشکەفتی",summary:"خوینبەربوونا مەترسیدار (hemorrhage) و شکەستنا هەستیان (fracture) ژ مەترسیدارترین برینداریانن. کارێ دروست د خولەکێن ئێکێ دا دشێت جوداهییێ د ناڤبەرا ژیان و مرنێ دا چێبکەت. ئەڤ وانە ل گۆر بەرنامێ Stop the Bleed یە.",blocks:[{heading:"خوینبەربوونا مەترسیدار و ڕاگرتنا وێ",body:`جۆرێن خوینبەربوونێ:
• ژ شەریانێ (Arterial): سوورێ گەش، ب پژین و دگەل لێدانا دلی دهێت. مەترسیدارترینە!
• ژ وەریدێ (Venous): سوورێ تاری، ب بەردەوامی دهێت
• ژ دەمارێن گەلەک باریک (Capillary): هێدی، دلۆپ دلۆپ

ڕاگرتنا خوینێ (Stop the Bleed):
1. سەلامەتییا خوە بپارێزە (دەستکێشان بکە) و گازی ١٢٢ بکە، یان ژ کەسەکی بخوازە گازی بکەت
2. فشارا ڕاستەوخوە (Direct Pressure): قوماشەکێ پاقژ دانە سەر برینێ و ب هەردوو دەستان ب هێز و بێ ڕاوەستیان فشار بدە
3. ئەگەر قوماش ب خوینێ تژی بوو، لانەبە؛ قوماشەکێ دی ل سەر دانە و فشارێ بەردەوام بکە
4. برینا کوور (ل ڕان، بن مل یان ستۆی): برینێ ب قوماشێ پاقژ (gauze) تژی بکە (Wound Packing) و پاشان ب هێز فشار بدە. ئەڤە بۆ برینێن سنگ و زکی نینە
5. خوینبەربوونا مەترسیدار ل دەست یان پێ: تۆرنیکێتێ (Tourniquet) زوو ببەستە، ٥–٧ سم ل سەرتر ژ برینێ`,image:"media/images/bleeding_control.png"},{heading:"شکەستنا هەستیان",body:`جۆرێن شکەستنێ:
• داخستی (Closed): هەستی یێ شکەستی یە بەلێ پێست یێ ساخلەمە
• ڤەکری (Open): هەستی پێستی دبڕیت و دەردکەڤیت؛ مەترسیدارترە!

نیشان:
• ئێش، وەرەم (swelling)، شینبوون
• شێوەیێ نەئاسایی یێ ئەندامی، نەشیانا لڤاندنا وی
• دەنگێ شکەستنێ دەمێ برینداربوونێ

هاریکاری:
1. ئەندامێ بریندار نەلڤینە!
2. جەبیرە (Splint): ئەندامی ل سەر وی شێوەیێ کو هەی جێگیر بکە
3. جومگەیێن سەری و خوارێ جهێ شکەستنێ جێگیر بکە
4. شکەستنا ڤەکری: ل دەوروبەرێ برینێ فشار بدە بۆ ڕاگرتنا خوینێ و برینێ ب قوماشەکێ پاقژ بپێچە
5. هەول نەدە هەستیێ دەرکەفتی بزڤڕینیە جهێ وی!
6. گازی ١٢٢ بکە`,image:"media/images/fracture_care.png"},{heading:"تۆرنیکێت (Tourniquet)",body:`تۆرنیکێت بۆ خوینبەربوونا مەترسیدار ل دەست یان پێ دهێتە بکارئینان (life-threatening limb bleeding). ئەگەر خوین ب هێز دپژیت یان فشار بەس نەبوو، زوو بکار بینە؛ نەهێلە بۆ دووماهییێ.

جهـ: ٥–٧ سم ل سەرتر ژ برینێ (د ناڤبەرا برین و لەشی دا)، نە ل سەر جومگەیێ. ئەگەر جهێ برینێ نەدیار بوو، ل بلندترین جهێ ئەندامی ببەستە.
چەوا:
1. تۆرنیکێتێ ل دەوری ئەندامی بپێچە
2. داوییا وێ ب هێز بکێشە و قایم بکە
3. دارکێ وێ (Windlass) بزڤڕینە هەتا خوین ب تەمامی ڕادوەستیت
4. دارکی جێگیر بکە
5. دەمێ بەستنا تۆرنیکێتێ بنڤیسە!

تۆرنیکێت ئێشێ چێدکەت؛ ئەڤە ئاسایی یە. چ جاران سست نەکە و ڤەنەکە؛ تەنێ ستافێ پزیشکی لادبەت.`,image:"media/images/tourniquet.png"}],examples:["شەریانی = سوورێ گەش + ب پژین","وەریدی = سوورێ تاری + ب بەردەوامی","فشارا ڕاستەوخوە و ب هێز = هەنگاڤا ئێکێ","قوماش ب خوینێ تژی بوو؟ لانەبە، یێ دی ل سەر دانە","برینا کوور: تژیکرنا برینێ (Wound Packing) + فشار","تۆرنیکێت: ٥–٧ سم ل سەرتر ژ برینێ، زوو","شکەستنا داخستی بەرامبەر ڤەکری","دەمێ بەستنا تۆرنیکێتێ بنڤیسە و چ جاران سست نەکە"],tips:["فشارا ڕاستەوخوە ئێکەم کارە","فشارێ بەرنەدە!","خوینبەربوونا مەترسیدار ل دەست یان پێ: تۆرنیکێت زوو","دەمێ بەستنێ بنڤیسە"],warnings:["پشتی بەستنا تۆرنیکێتێ، چ جاران سست نەکە و لانەبە! تەنێ ستافێ پزیشکی لادبەت. دەمێ بەستنێ ل سەر تۆرنیکێتێ یان ل سەر ئەنییا برینداری بنڤیسە."],realCase:"ل سلێمانیێ، قوتابییەکێ پۆلا ١١ێ کو فێری هەوارهاتنا ئێکێ بووی، دیت کو خوین ب پژین ژ برینا هەڤالێ وی دهێت (خوینبەربوونا شەریانی). وی ئێکسەر ب هێز فشارا ڕاستەوخوە دا سەر برینێ و بەرنەدا هەتا ئەمبوولانس هاتی، و هەڤالەکێ دی گازی ١٢٢ کر. دکتۆران گۆت کو کارێ وی یێ زوو ژیانا هەڤالێ وی پاراست.",video:"media/videos/lesson_bleeding.mp4",game:{instruction:"دەربارەی خوینبەربوونێ، کیژ گۆتن دروستن؟",items:[{text:"خوینا شەریانی: سوورێ گەش و ب پژین",emoji:"❤️",correct:!0},{text:"خوینا شەریانی: سوورێ تاری و هێدی",emoji:"🔵",correct:!1},{text:"فشارا ڕاستەوخوە و ب هێز ئێکەم هەنگاڤە",emoji:"✋",correct:!0},{text:"ئاڤێ ل سەر برینێ بڕێژە دا خوین ڕاوەستیت",emoji:"💧",correct:!1}]},activity:{prompt:"د تاقیگەهێدا، دەستێ قوتابییەکی ب شووشەیێ هاتە بڕین و خوینبەربوونەکا مەزن هەیە. خوین ب پژین و ب ڕەنگێ سوورێ گەش دهێت. دێ چ کەی؟",image:"media/images/activity_bleeding.png",options:[{text:"دەستکێشان دکەم، ب قوماشەکێ پاقژ فشارا ڕاستەوخوە و ب هێز ددەم و بەرنادەم، و ب دەنگ هاریکارییێ دخوازم دا مامۆستا گازی ١٢٢ بکەت و کیتا هەوارهاتنا ئێکێ بینیت. ئەگەر خوین ڕانەوەستیا، تۆرنیکێتێ ٥–٧ سم ل سەرتر ژ برینێ دبەستم و دەمی دنڤیسم",correct:!0},{text:"ئاڤێ ل سەر برینێ دڕێژم",correct:!1},{text:"دهێلم بلا خوین ب خوە ڕاوەستیت",correct:!1},{text:"دڕەڤم",correct:!1}]},quiz:[{question:"تۆرنیکێت ل کیڤە دهێتە بەستن؟",options:[{text:"٥–٧ سم ل سەرتر ژ برینێ (د ناڤبەرا برین و لەشی دا)",correct:!0,feedback:"دروستە! و دەمێ بەستنێ بنڤیسە."},{text:"ل سەر برینێ ب خوە",correct:!1,feedback:"نەخێر!"},{text:"ل سەر جومگەیێ",correct:!1,feedback:"نەخێر! نە ل سەر جومگەیێ؛ ل سەرتر ژ جومگەیێ ببەستە."}]},{question:"شکەستنا ڤەکری (Open) واتایا چ یە؟",options:[{text:"هەستی پێستی دبڕیت و دەردکەڤیت",correct:!0,feedback:"دروستە!"},{text:"هەستی یێ شکەستی یە بەلێ پێست یێ ساخلەمە",correct:!1,feedback:"ئەو شکەستنا داخستی یە!"},{text:"تەنێ ئێش هەیە",correct:!1,feedback:"نەخێر!"}]}]},{id:11,icon:"ShieldAlert",accent:"#db2777",title:"هێمایێن سەلامەتییێ یێن نێڤدەولەتی",subtitle:"GHS، NFPA و ISO",summary:"هێمایێن سەلامەتییێ یێن نێڤدەولەتی (GHS، NFPA 704 و ISO 7010) زمانەکێ جیهانی نە بۆ ئاگەهدارکرنێ. د ڤێ وانێ دا ئەم فێری ڤان سیستەم و ستانداردان دبین.",blocks:[{heading:"GHS: سیستەمێ جیهانی",body:`GHS (Globally Harmonized System) ٩ هێمایێن سەرەکی هەنە:
1. تەقینەر (Explosive): بۆمبا تەقیای
2. سووتەنی (Flammable): ئاگر
3. ئۆکسیدکەر (Oxidizer): ئاگر ل سەر بازنەیێ
4. غازا ب فشار (Compressed Gas): بوتلا غازێ
5. داخوەر (Corrosive): دلۆپ ل سەر دەستی و کانزای
6. ژەهرا کوژەک (Acute Toxicity): کەللێ سەری و هەستی
7. ئێشاندن و زیانا سڤک (Irritant/Harmful): نیشانا (!)
8. مەترسییا گران بۆ تەندروستیێ (Health Hazard): لەشێ مرۆڤی ب ستێرەکێ
9. مەترسی بۆ ژینگەهێ (Environmental): ماسی و دار

هەر هێمایەک ڕەشە، ل سەر بنەکێ سپی و د ناڤ لۆزنەکێ (Diamond) ب لێڤێن سوور دا. GHS هێمایا تیشکدەر (ڕادیۆئاکتیڤ) تێدا نینە؛ ئەو هێما د ISO 7010 و ڕێنمایێن ڤەگوهاستنێ دا هەیە.`,image:"media/images/ghs_all.png"},{heading:"لۆزنا NFPA 704",body:`لۆزنا NFPA 704 ژ ٤ پشکان پێکدهێت:
• سوور (سەری) = سووتەنی: ٠–٤ (٠ = ئاگر ناگریت، ٤ = گەلەک سووتەنی)
• شین (چەپێ) = تەندروستی: ٠–٤ (٠ = بێ مەترسی، ٤ = کوژەک)
• زەرد (ڕاستێ) = نەجێگیری: ٠–٤ (٠ = جێگیر، ٤ = دشێت بتەقیت)
• سپی (خوارێ) = مەترسیێن تایبەت: OX = ئۆکسیدکەر، W ب هێلەکێ ل سەر = ئاڤێ بکار نەئینە، SA = غازا خەندقێنەر

نموونە: بەنزین = سوور ٣، شین ١، زەرد ٠`,image:"media/images/nfpa_diamond.png"},{heading:"هێمایێن ISO 7010",body:`ISO 7010 ستاندارا نێڤدەولەتی یا هێمایێن سەلامەتییێ یە:
• قەدەغەکرن (Prohibition): بازنەیەکا سوور ب هێلەکا سوور یا لار. نموونە: «نەچە ژوور»، «جگارێ نەکێشە»
• هشیاری (Warning): سێگۆشەیەکا زەرد ب لێڤێن ڕەش. نموونە: مەترسییا گشتی، کارەبا، تیشکدەر (ڕادیۆئاکتیڤ)
• فەرمان (Mandatory): بازنەیەکا شین. نموونە: «چاڤیلکێن پاراستنێ بکە»، «دەستکێشان بکە»
• سەلامەتی (Safe Condition): چارگۆشەیەکا کەسک. نموونە: دەرکەفتنا تەنگاڤیێ، هەوارهاتنا ئێکێ، تەلەفۆنا تەنگاڤیێ
• ئامێرێن ئاگری (Fire Equipment): چارگۆشەیەکا سوور. نموونە: تەمرینک، شلانگا ئاگری`,image:"media/images/iso_signs.png"}],examples:["GHS: کەللێ سەری = ژەهراوی","NFPA سوور = سووتەنی","NFPA شین = تەندروستی","NFPA زەرد = نەجێگیری","NFPA سپی = مەترسیێن تایبەت (OX، W، SA)","ISO: بازنەیا سوور = قەدەغە","ISO: سێگۆشەیا زەرد = هشیاری","ISO: چارگۆشەیا کەسک = سەلامەتی"],tips:["٩ هێمایێن GHS فێر ببە","٤ ڕەنگێن NFPA 704 بزانە","ISO: سوور = قەدەغە، زەرد = هشیاری، شین = فەرمان، کەسک = سەلامەتی"],warnings:["هێمایان ب جددی وەربگرە! ئەو بۆ پاراستنا ژیانا تە نە. ئەگەر تە هێمایەکا نەناس دیت، نێزیک نەبە و ژ پسپۆڕان بپرسە."],realCase:"ل کارگەهەکێ ل زاخۆ، کارمەندەکێ نوی لۆزنا NFPA ل سەر تانکەکا کیمیایی نەخواندبوو. وی ب ئاڤێ هەول دا ئاگرەکی ڤەمرینیت، بەلێ د پشکا سپی دا W ب هێلەکێ ل سەر هاتبوو نڤیسین (ئاڤێ بکار نەئینە!). ئاگر مەزنتر لێ هات. ئەگەر وی هێما ناسیبان، ئەڤ ڕووداوە نەدبوو.",video:"media/videos/lesson_symbols.mp4",game:{instruction:"کیژ گۆتن دروستن؟ یێن دروست هەلبژێرە:",items:[{text:"NFPA: شین = تەندروستی",emoji:"🔵",correct:!0},{text:"NFPA: سوور = نەجێگیری",emoji:"🔴",correct:!1},{text:"ISO: کەسک = سەلامەتی",emoji:"🟢",correct:!0},{text:"NFPA: زەرد = سووتەنی",emoji:"🟡",correct:!1}]},activity:{prompt:"د تاقیگەهێدا تانکەک هەیە ب لۆزنا NFPA: سوور ٤، شین ٣، زەرد ٢، سپی OX. واتایا وێ چ یە و دێ چەوا مامەلێ دگەل کەی؟",image:"media/images/activity_symbols.png",options:[{text:"گەلەک سووتەنی یە (٤)، بۆ تەندروستیێ گەلەک مەترسیدارە (٣)، ب ڕادەیەکێ نەجێگیرە (٢) و ئۆکسیدکەرە (OX). PPE یا گونجای دکەم و ب هشیاری مامەلێ دکەم؛ دوور ژ ئاگری و ماددێن سووتەنی دهێلم",correct:!0},{text:"سەلامەتە",correct:!1},{text:"نزانم",correct:!1},{text:"ئاڤێ دڕێژمە سەر",correct:!1}]},quiz:[{question:"GHS چەند هێمایێن سەرەکی هەنە؟",options:[{text:"٩",correct:!0,feedback:"دروستە!"},{text:"٤",correct:!1,feedback:"ئەو ٤ ڕەنگێن NFPA نە!"},{text:"٦",correct:!1,feedback:"نەخێر!"}]},{question:"د ISO دا، سێگۆشەیا زەرد واتایا چ یە؟",options:[{text:"هشیاری و مەترسی",correct:!0,feedback:"دروستە!"},{text:"قەدەغەکرن",correct:!1,feedback:"ئەو بازنەیا سوورە!"},{text:"سەلامەتی",correct:!1,feedback:"ئەو چارگۆشەیا کەسکە!"}]}]},{id:12,icon:"Users",accent:"#4f46e5",title:"سەرپەرشتی ل دەمێ تەنگاڤیان",subtitle:"بڕیاردان و ڕێبەرییا تیمێ",summary:"سەرپەرشتی ل دەمێ تەنگاڤیان کارەکێ تایبەتە: بڕیاردان د بن فشارێ دا و ب لەز، ڕێبەرییا تیمێ و هەماهەنگی دگەل دامەزراوەیان. ئەڤ وانە قوتابیان ئامادە دکەت داکو ببنە ڕێبەرێن سەلامەتییێ.",blocks:[{heading:"بڕیاردان ل دەمێ تەنگاڤیان",body:`مۆدێلا OODA Loop:
• Observe (چاڤدێری بکە): بارودۆخێ دەوروبەری ببینە و بپشکنە
• Orient (تێبگەهە): زانیارییان شرۆڤە بکە و مەترسییان بناسە
• Decide (بڕیار بدە): پلانەکا بلەز و سەلامەت هەلبژێرە
• Act (کار بکە): پلانێ جێبەجێ بکە

بنەما:
• ب لەز بڕیار بدە؛ بڕیارەکا نە تەمام باشترە ژ بڕیار نەدانێ
• زانیارییان کۆم بکە، بەلێ ل هیڤییا هەمییان نەمینە
• تیمێ ئاگەهدار بکە
• چاڤدێری بکە و ئەگەر پێدڤی بوو، پلانێ بگوهۆڕە`,image:"media/images/ooda_loop.png"},{heading:"ڕێبەرییا تیمێ",body:`• ڕۆلان دابەش بکە: هەر کەسەک بزانیت دێ چ کەت
• پەیوەندییا ڕوون: فەرمانێن کورت و ڕوون بدە
• گوهداری بکە: تیم زانیارییان ددەتە تە
• هێمنی: ئەگەر تو بترسی، تیم ژی دێ ترسیت
• پشتەڤانی: هاریکارییا ئەندامێن تیمێ بکە و پشتەڤانییا وان بکە

ل قوتابخانێ:
• تو = بەرپرسێ سەلامەتییا پۆلێ
• ڕۆل: ئاگەهدارکرن، دەرئێخستن، ژمارتن، هەوارهاتنا ئێکێ
• ڕاهێنان ب ڕێک و پێک`,image:"media/images/team_leadership.png"},{heading:"هەماهەنگی و پەیوەندی",body:`ل دەمێ تەنگاڤیان پەیوەندی گرنگترین تشتە.

ژمارێن تەنگاڤیێ ل هەرێما کوردستانێ:
• ١١٥ = بەرگرییا شارستانی (ئاگر، ڕزگارکرن، کارەسات)
• ١٢٢ = ئەمبوولانس (تەنگاڤییێن پزیشکی)
• ١٠٤ = پۆلیس

ڕاگەهاندن:
• مێگافۆن / سایرین
• مۆبایل و گرووپێن پەیامان (WhatsApp)
• ڕادیۆ

ڕاپۆرت:
• چ چێبوو؟
• ل کیڤە؟
• چەند بریندار یان زیانلێکەفتی هەنە؟
• چ هاریکاری پێدڤییە؟`,image:"media/images/communication.png"}],examples:["OODA: Observe-Orient-Decide-Act","ڕۆلان دابەش بکە","فەرمانێن کورت و ڕوون","دەنگێ خوە هێمن بهێلە","١١٥ ئاگر و ڕزگارکرن، ١٢٢ ئەمبوولانس، ١٠٤ پۆلیس","ڕاپۆرت: چ + ل کیڤە + چەند + چ پێدڤییە","چاڤدێری بکە و ئەگەر پێدڤی بوو پلانێ بگوهۆڕە","پەیوەندی و ڕاگەهاندن = ژیان"],tips:["OODA Loop فێر ببە","ڕۆلان دابەش بکە","هێمن بمینە","پەیوەندییا ڕوون"],warnings:["سەرپەرشتی ل دەمێ تەنگاڤیان ئەو نینە کو تو خوە بێخیە مەترسیێ! واتایا وێ ئەوە کو ب زیرەکی و هێمنی تیمێ ڕێبەری بکەی و بڕیارێن دروست بدەی."],realCase:"ل قوتابخانەکێ ل سلێمانیێ، قوتابییەکا پۆلا ١٢ێ کو فێری سەرپەرشتیێ بووی، دەمێ عەردەهەژینەک هاتی ب هێمنی پۆلا خوە ڕێبەری کر: دەمێ هەژینێ هەمییان خوە ل بن مێزان ڤەشارت، و پشتی هەژین ڕاوەستیای وێ ڕۆل دابەش کرن، هاریکارییا قوتابیێن خودان پێدڤییێن تایبەت کر و د ٢ خولەکاندا هەمی گەهشتنە خالا کۆمبوونێ. مامۆستای گۆت کو وێ ڕۆژێ هێمنییا وێ گەلەک هاریکاری کر.",video:"media/videos/lesson_leadership.mp4",game:{instruction:"د OODA Loop دا، هەنگاڤا ئێکێ چ یە؟",items:[{text:"Observe (چاڤدێری بکە)",emoji:"👀",correct:!0},{text:"Act (کار بکە)",emoji:"🏃",correct:!1},{text:"Decide (بڕیار بدە)",emoji:"🧠",correct:!1},{text:"Orient (تێبگەهە)",emoji:"🗺️",correct:!1}]},activity:{prompt:"تو د وانێ دا یی و دەنگێ تەقینەکا مەزن ژ تاقیگەها کیمیایێ دهێت. مامۆستا ل وێرێ نینە. تو بەرپرسێ سەلامەتییا پۆلێ یی و ١٨ قوتابی د پۆلێ دا هەنە. دێ چ کەی؟",image:"media/images/activity_leadership.png",options:[{text:"ب ڕێکا OODA: بارودۆخی دپشکنم، ئەرکان دابەش دکەم (ئاگەهدارکرن + دەرکەفتن + هاریکاری)، ب ڕێزبەندی ب پلەکانان بەرەڤ خالا کۆمبوونێ دەردکەڤین، کەسان دژمێرم و گازی ١١٥ و ١٢٢ دکەم",correct:!0},{text:"ب لەز ب تەنێ دڕەڤم",correct:!1},{text:"دچمە تاقیگەها کیمیایێ",correct:!1},{text:"تەنێ ل هیڤیێ دمینم",correct:!1}]},quiz:[{question:"OODA Loop ژ چەند هەنگاڤان پێکدهێت؟",options:[{text:"٤: Observe، Orient، Decide، Act",correct:!0,feedback:"دروستە!"},{text:"٣",correct:!1,feedback:"نەخێر!"},{text:"٦",correct:!1,feedback:"نەخێر!"}]},{question:"ل دەمێ تەنگاڤیان، گرنگترین تشت چ یە؟",options:[{text:"پەیوەندییا ڕوون و بلەز",correct:!0,feedback:"دروستە!"},{text:"ڕەڤین",correct:!1,feedback:"نەخێر!"},{text:"ل هیڤیێ مان",correct:!1,feedback:"نەخێر!"}]}]}],t={lessons:e};export{t as default,e as lessons};
